INSERT INTO posts (title, content, author, phone, product, password_hash, is_secret, reply, replied_at, created_at, updated_at)
WITH RECURSIVE seq(n) AS (
  SELECT 1 UNION ALL SELECT n + 1 FROM seq WHERE n < 2444
),
calc AS (
  SELECT n,
         CAST(((n - 1) * 727) / 2444 AS INTEGER) AS d,
         CASE n % 43 WHEN 0 THEN '사무실 기업용 인터넷 1G 신규 설치 문의' WHEN 1 THEN '기업용 인터넷 500M 견적 요청' WHEN 2 THEN '사무실 이전 인터넷 이전 설치 문의' WHEN 3 THEN '타사에서 KT 이동 시 위약금 지원 문의' WHEN 4 THEN '고정 IP 추가 신청 가능한가요' WHEN 5 THEN '지점 2곳 인터넷 동시 개통 문의' WHEN 6 THEN '설치 가능 지역 확인 요청' WHEN 7 THEN '인터넷 속도 상향 절차 문의' WHEN 8 THEN '소규모 사무실 저렴한 요금제 문의' WHEN 9 THEN '랜공사 포함 설치 견적 요청' WHEN 10 THEN '기업전화 6회선 신규 개통 문의' WHEN 11 THEN '기업전화·인터넷 결합 할인 문의' WHEN 12 THEN '기존 번호 그대로 이전 가능한가요' WHEN 13 THEN '무선 인터넷 전화기 추가 구매 문의' WHEN 14 THEN '녹취 기능 사용 방법 문의' WHEN 15 THEN '내선 구성·돌려주기 기능 문의' WHEN 16 THEN '단말기 종류와 가격 문의' WHEN 17 THEN '사무실 전화 3회선 견적 요청' WHEN 18 THEN '대표번호 착신전환 설정 문의' WHEN 19 THEN '기업전화 요금 명세서 요청' WHEN 20 THEN 'GIGA office 개통 절차 문의' WHEN 21 THEN '전용회선 이중화 구성 상담' WHEN 22 THEN '1G 전용회선 월 요금 문의' WHEN 23 THEN '공장용 전용회선 설치 가능 여부' WHEN 24 THEN '계약 기간·해지 조건 문의' WHEN 25 THEN '본사-지사 구간 전용선 상담' WHEN 26 THEN '사무실 IPTV 2대 설치 견적 요청' WHEN 27 THEN '휴게실 IPTV 설치 가능한가요' WHEN 28 THEN 'IPTV 채널 구성표 요청' WHEN 29 THEN '셋탑박스 임대료 문의' WHEN 30 THEN '2대 이상 할인 적용 문의' WHEN 31 THEN '회의실 IPTV 설치 상담' WHEN 32 THEN '결합 상품 할인 기준 문의' WHEN 33 THEN '개통까지 소요 기간 문의' WHEN 34 THEN '방문 상담 예약 문의' WHEN 35 THEN '사무실 랜공사 가능 여부' WHEN 36 THEN '사업자등록 전 가입 가능한가요' WHEN 37 THEN '여러 지점 대표번호 연결 문의' WHEN 38 THEN '세금계산서 발행 문의' WHEN 39 THEN '단체 가입 할인 문의' WHEN 40 THEN '설치 후 A/S 신청 방법 문의' WHEN 41 THEN '계약서 사본 요청드립니다' WHEN 42 THEN '요금 납부 방법 변경 문의' END AS ttl,
         CASE n % 43 WHEN 0 THEN 'KT 기업용 인터넷' WHEN 1 THEN 'KT 기업용 인터넷' WHEN 2 THEN 'KT 기업용 인터넷' WHEN 3 THEN 'KT 기업용 인터넷' WHEN 4 THEN 'KT 기업용 인터넷' WHEN 5 THEN 'KT 기업용 인터넷' WHEN 6 THEN 'KT 기업용 인터넷' WHEN 7 THEN 'KT 기업용 인터넷' WHEN 8 THEN 'KT 기업용 인터넷' WHEN 9 THEN 'KT 기업용 인터넷' WHEN 10 THEN 'KT 기업인터넷 전화' WHEN 11 THEN 'KT 기업인터넷 전화' WHEN 12 THEN 'KT 기업인터넷 전화' WHEN 13 THEN 'KT 기업인터넷 전화' WHEN 14 THEN 'KT 기업인터넷 전화' WHEN 15 THEN 'KT 기업인터넷 전화' WHEN 16 THEN 'KT 기업인터넷 전화' WHEN 17 THEN 'KT 기업인터넷 전화' WHEN 18 THEN 'KT 기업인터넷 전화' WHEN 19 THEN 'KT 기업인터넷 전화' WHEN 20 THEN 'GIGA office (전용회선)' WHEN 21 THEN 'GIGA office (전용회선)' WHEN 22 THEN 'GIGA office (전용회선)' WHEN 23 THEN 'GIGA office (전용회선)' WHEN 24 THEN 'GIGA office (전용회선)' WHEN 25 THEN 'GIGA office (전용회선)' WHEN 26 THEN 'KT IPTV' WHEN 27 THEN 'KT IPTV' WHEN 28 THEN 'KT IPTV' WHEN 29 THEN 'KT IPTV' WHEN 30 THEN 'KT IPTV' WHEN 31 THEN 'KT IPTV' WHEN 32 THEN '기타 문의' WHEN 33 THEN '기타 문의' WHEN 34 THEN '기타 문의' WHEN 35 THEN '기타 문의' WHEN 36 THEN '기타 문의' WHEN 37 THEN '기타 문의' WHEN 38 THEN '기타 문의' WHEN 39 THEN '기타 문의' WHEN 40 THEN '기타 문의' WHEN 41 THEN '기타 문의' WHEN 42 THEN '기타 문의' END AS prd,
         REPLACE(CASE n % 12 WHEN 0 THEN '안녕하세요. 현재 사용 중인 회선 약정이 만료되어 KT로 이동을 검토하고 있습니다. 설치 희망 지역은 서울 구로구 인근 사무실이며, 사용 인원은 {n}명 정도입니다. 가능한 요금제와 설치 소요 기간, 랜공사 비용도 함께 안내 부탁드립니다.' WHEN 1 THEN '사무실 이전을 앞두고 인터넷과 전화를 함께 신청하려고 합니다. 이전 설치 일정 조율이 가능한지, 추가 비용이 발생하는지 궁금합니다.' WHEN 2 THEN '현재 타사 인터넷을 사용 중인데 속도가 느려 변경을 고려하고 있습니다. 사무실 면적은 약 {n}평이고 직원은 {n}명입니다. 설치 가능 여부와 요금 안내 부탁드립니다.' WHEN 3 THEN '기업전화 신규 개통 문의드립니다. 필요 회선은 {n}회선 정도이며 대표번호와 내선 구성도 함께 검토하고 있습니다.' WHEN 4 THEN '휴게실과 회의실에 IPTV를 설치하려고 합니다. 총 2대 예정이며 설치 비용과 월 이용료를 안내 부탁드립니다.' WHEN 5 THEN '전용회선 사용 중인데 속도 대비 요금이 높아 재검토 중입니다. 개선 가능한 상품이 있는지 문의드립니다.' WHEN 6 THEN '지점을 새로 열게 되어 인터넷과 전화를 함께 신청하려 합니다. 개통까지 걸리는 기간과 설치 가능 요일을 알려주세요.' WHEN 7 THEN '기존에 사용하던 번호를 그대로 유지할 수 있는지 문의드립니다. 사무실 이전 예정이라 이전 설치 절차도 안내 부탁드립니다.' WHEN 8 THEN '직원 {n}명 규모 사무실입니다. 인터넷과 전화를 결합하면 월 얼마 정도인지 대략적인 금액이라도 알고 싶습니다.' WHEN 9 THEN '이번 달 안으로 개통을 희망합니다. 방문 상담 가능하시면 평일 오후로 부탁드립니다.' WHEN 10 THEN '본사와 물류창고 두 곳에 각각 회선이 필요합니다. 두 곳 동시 진행 시 할인이나 설치 일정 조율이 가능한지 문의드립니다.' WHEN 11 THEN '현재 사용 중인 단말기를 그대로 쓸 수 있는지, 교체가 필요한지 궁금합니다. 단말기 임대와 구매 중 어떤 쪽이 유리한가요?' END, '{n}', CAST(2 + (n % 19) AS TEXT)) AS bdy,
         CASE n % 3 WHEN 0 THEN '안녕하세요, KT 공식가입센터입니다. 문의주신 내용 확인했습니다. 해당 지역은 기가 회선 설치가 가능하며 사무실 규모에 맞춘 결합 상품을 추천드립니다. 설치까지는 신청 후 영업일 기준 3~5일 소요되며, 기업전화 결합 시 구내공사는 무료로 지원됩니다.' WHEN 1 THEN '안녕하세요, KT 공식가입센터입니다. 요청하신 회선 수 기준으로 견적을 정리해 안내드리겠습니다. 방문 상담도 가능하니 편하신 시간대를 회신해 주시면 담당자가 일정을 잡아드립니다.' WHEN 2 THEN '안녕하세요, KT 공식가입센터입니다. 설치 가능 여부 확인 결과 문제 없이 진행 가능합니다. 약정 기간과 사은 혜택까지 포함해 담당자가 곧 연락드리겠습니다.' END AS rpl
  FROM seq
)
SELECT ttl, bdy,
  (substr('김이박최정강조윤장임한오서신권황안송전홍유고문양손배백허남심노하곽성차주우구', 1 + (n % 40), 1) || CASE n % 40 WHEN 0 THEN '민수' WHEN 1 THEN '서연' WHEN 2 THEN '지훈' WHEN 3 THEN '수진' WHEN 4 THEN '현우' WHEN 5 THEN '지영' WHEN 6 THEN '동혁' WHEN 7 THEN '은지' WHEN 8 THEN '성민' WHEN 9 THEN '미경' WHEN 10 THEN '재현' WHEN 11 THEN '보라' WHEN 12 THEN '태윤' WHEN 13 THEN '소영' WHEN 14 THEN '기범' WHEN 15 THEN '하늘' WHEN 16 THEN '정민' WHEN 17 THEN '유진' WHEN 18 THEN '상훈' WHEN 19 THEN '다은' WHEN 20 THEN '영식' WHEN 21 THEN '혜림' WHEN 22 THEN '준호' WHEN 23 THEN '가영' WHEN 24 THEN '진우' WHEN 25 THEN '나래' WHEN 26 THEN '병철' WHEN 27 THEN '수현' WHEN 28 THEN '원석' WHEN 29 THEN '지아' WHEN 30 THEN '경수' WHEN 31 THEN '세림' WHEN 32 THEN '창민' WHEN 33 THEN '예진' WHEN 34 THEN '대호' WHEN 35 THEN '민지' WHEN 36 THEN '승우' WHEN 37 THEN '다현' WHEN 38 THEN '규민' WHEN 39 THEN '소라' END) AS a1,
  '010' || printf('%08d', (n * 7919) % 100000000) AS phone,
  prd, 'seed', 0,
  CASE WHEN n % 10 < 6 THEN rpl ELSE NULL END,
  CASE WHEN n % 10 < 6 THEN strftime('%Y-%m-%d %H:%M:%S','2024-11-06','+'||d||' days','+'||(540 + (n*53)%540)||' minutes') ELSE NULL END,
  strftime('%Y-%m-%d %H:%M:%S','2024-11-06','+'||d||' days','+'||(540 + (n*53)%540)||' minutes'),
  strftime('%Y-%m-%d %H:%M:%S','2024-11-06','+'||d||' days','+'||(540 + (n*53)%540)||' minutes')
FROM calc;

INSERT INTO posts (title, content, author, phone, product, password_hash, is_secret, reply, replied_at, created_at, updated_at) VALUES
('사무실 기업용 인터넷 1G 신규 설치 문의','안녕하세요. 이번 달 안에 개통을 희망합니다. 사무실은 구로구 부일로 인근이며 직원 8명 규모입니다. 요금제와 설치 일정 안내 부탁드립니다.','김민수','01024839175','KT 기업용 인터넷','seed',0,'안녕하세요, KT 공식가입센터입니다. 해당 지역 설치 가능 확인되었으며 1G 회선 기준 월 요금과 설치 일정을 정리해 안내드리겠습니다.','2026-11-03 15:20:00','2026-11-03 10:12:00','2026-11-03 15:20:00'),
('기업전화 6회선·대표번호 동시 신청 문의','기업전화 6회선과 대표번호를 함께 신청하려고 합니다. 내선 구성과 착신전환 설정도 가능한지 문의드립니다.','이서연','01037552048','KT 기업인터넷 전화','seed',0,NULL,NULL,'2026-11-03 14:05:00','2026-11-03 14:05:00'),
('KT IPTV 2대 설치 견적 요청','휴게실과 회의실에 IPTV 2대를 설치하려고 합니다. 셋탑 임대료와 2대 이상 할인 적용 여부 문의드립니다.','박지훈','01044126630','KT IPTV','seed',0,NULL,NULL,'2026-11-03 16:48:00','2026-11-03 16:48:00'),
('GIGA office 전용회선 이중화 상담','본사와 지사 구간 전용회선 이중화 구성을 검토 중입니다. 회선 2개 구성 시 비용과 개통 기간 문의드립니다.','최수진','01055871092','GIGA office (전용회선)','seed',0,'안녕하세요, KT 공식가입센터입니다. 이중화 구성은 회선 2회선 기준으로 견적을 정리해 안내드리며, 개통까지는 영업일 기준 5~7일 소요됩니다.','2026-11-04 11:30:00','2026-11-04 09:40:00','2026-11-04 11:30:00'),
('사무실 이전 인터넷·전화 이전 설치 문의','다음 주 사무실 이전 예정입니다. 기존 인터넷과 전화를 그대로 이전할 수 있는지, 추가 비용이 있는지 궁금합니다.','정현우','01066204418','KT 기업용 인터넷','seed',0,NULL,NULL,'2026-11-04 13:22:00','2026-11-04 13:22:00'),
('타사 이동 시 위약금 지원 문의','현재 타사 인터넷을 사용 중이며 약정이 3개월 남았습니다. KT 이동 시 위약금 지원이 가능한지 문의드립니다.','강지영','01077398851','KT 기업용 인터넷','seed',0,NULL,NULL,'2026-11-04 16:10:00','2026-11-04 16:10:00'),
('기업용 인터넷 500M 견적 요청','직원 5명 규모 사무실입니다. 500M 상품 견적과 기업전화 결합 시 할인 금액 안내 부탁드립니다.','조윤서','01088912466','KT 기업용 인터넷','seed',0,NULL,NULL,'2026-11-05 09:28:00','2026-11-05 09:28:00'),
('방문 상담 예약 문의','개통 전에 방문 상담을 받고 싶습니다. 평일 오후 2시 이후면 가능한데 일정 조율 부탁드립니다.','윤동혁','01091450073','기타 문의','seed',0,NULL,NULL,'2026-11-05 11:02:00','2026-11-05 11:02:00'),
('기업전화 단말기 종류와 가격 문의','기업전화 신규 개통 시 제공되는 단말기 종류와 임대·구매 가격 차이를 알고 싶습니다.','장은지','01010553387','KT 기업인터넷 전화','seed',0,NULL,NULL,'2026-11-05 12:40:00','2026-11-05 12:40:00');
